          "text": "git switch -c fix/promo-rounding"
        },
        {
          "kind": "edit",
          "text": "src/cart/total.ts",
          "diff": "+2 −1"
        },
        {
          "kind": "pass",
          "text": "npm test — пройдено"
        },
        {
          "kind": "info",
          "text": "git commit -m \"fix: round promo discounts to kopecks\""
        },
        {
          "kind": "meta",
          "text": "git push — по правилам проекта это делаете вы"
        },
        {
          "kind": "prompt",
          "text": "Запушил. Открой PR.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "gh pr create --title \"fix: round promo discounts to kopecks\""
        },
        {
          "kind": "done",
          "text": "PR открыт: что изменено, почему и как проверено."
        }
      ]
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Сообщение пишет агент, смысл проверяете вы",
