update public.guide_steps set lesson = $json${
  "minutes": 14,
  "outcome": "Вы встраиваете агента в свои скрипты и сервисы — через `claude -p` или Agent SDK — с ограниченными правами и разбором результата.",
  "blocks": [
    {
      "type": "text",
