-- economics: generated by `npm run guide:content` from content/guide/economics.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 12,
  "outcome": "Вы выбираете модель и уровень усердия под задачу, видите расходы и не платите за раздутый контекст.",
  "blocks": [
    {
      "type": "text",
      "text": "Работа агента стоит токенов: каждый запрос несёт весь контекст сессии, а каждый субагент делает свои запросы. На подписке Pro или Max токены расходуют лимиты плана, при оплате через API — деньги. Правила одни: на подписке вы экономите лимиты, на API — бюджет. Экономить — не значит брать самую дешёвую модель. Это значит не тратить на то, что не помогает результату."
    },
    {
      "type": "heading",
      "text": "Модель под задачу"
    },
    {
      "type": "list",
      "items": [
        "**`/model`** меняет модель в сессии, `claude --model` — при запуске. Короткие имена: `sonnet`, `opus`, `haiku`.",
        "**`opusplan`** — Opus думает в режиме планирования, Sonnet исполняет план. Сильное рассуждение там, где оно нужно, и дешёвое исполнение.",
        "**`/effort`** задаёт усердие: `low` для набросков, выше — для багов и крайних случаев, `xhigh` и `max` — для самых трудных задач. Уровень запоминается для модели, только `max` действует до конца сессии (шаг 3.4)."
      ]
    },
    {
      "type": "heading",
      "text": "Где видны расходы"
    },
    {
      "type": "command",
      "code": "/usage",
      "caption": "На подписке — шкалы лимитов плана и разбивка, что их расходует. При оплате через API — стоимость сессии. Там же токены по моделям и статистика кеша. `/cost` и `/stats` открывают тот же экран, а в безголовом режиме стоимость видна в поле `total_cost_usd`."
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса: разработчик смотрит /usage после долгой сессии и видит, что большая часть токенов ушла на повторное чтение раздутого контекста. Он очищает контекст, переключается на opusplan для следующей задачи, и каждый следующий запрос несёт меньше токенов.",
